window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[271]={"id":"271","numero":271,"titre":"Reflux gastro-œsophagien — hernie hiatale","objectifs":[{"id":"271-1","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la prévalence et les facteurs de risque du reflux gastro-œsophagien (RGO)","contenu":"<p><span class=\"kw-def\">Reflux gastro-œsophagien</span> (<span class=\"kw-def\">RGO</span>) = passage à travers le <span class=\"kw-def\">cardia</span> d'une partie du <span class=\"kw-bio\">contenu gastrique</span> dans l'œsophage, <strong>en dehors de tout effort de <span class=\"kw-clinique\">vomissement</span></strong>.</p>\n      <p>Le <span class=\"kw-clinique\">RGO</span> est <span class=\"kw-def\">physiologique</span> chez tout sujet ; il devient <span class=\"kw-alerte\">pathologique</span> dès qu'il s'accompagne de <span class=\"kw-clinique\">symptômes</span> ou de <span class=\"kw-imagerie\">lésions d'œsophagite</span>. Le reflux est alors :</p>\n      <ul>\n        <li>anormalement <span class=\"kw-clinique\">fréquent</span> ou <span class=\"kw-clinique\">prolongé</span> ;</li>\n        <li><strong>majoritairement <span class=\"kw-bio\">acide</span></strong>, plus rarement <span class=\"kw-bio\">peu acide</span> ou <span class=\"kw-bio\">non acide</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Prévalence</span></strong> — le <span class=\"kw-clinique\">pyrosis</span> est l'un des symptômes digestifs <span class=\"kw-clinique\">les</span> plus répandus :</p>\n      <table >\n        <thead><tr><th>Fréquence du <span class=\"kw-clinique\">pyrosis</span></th><th>Adultes concernés</th></tr></thead>\n        <tbody>\n          <tr><td>Au moins occasionnel</td><td><span class=\"kw-chiffre\">20-40 %</span></td></tr>\n          <tr><td>Hebdomadaire</td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td>Quotidien</td><td><span class=\"kw-chiffre\">2-5 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span></strong> du <span class=\"kw-clinique\">RGO</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Obésité</span> / <span class=\"kw-etio\">surcharge pondérale</span> = <strong>principal <span class=\"kw-def\">facteur de risque</span></strong> ;</li>\n        <li><span class=\"kw-etio\">Hernie hiatale</span> ;</li>\n        <li><span class=\"kw-etio\">Grossesse</span> ;</li>\n        <li><span class=\"kw-etio\">Alcool</span> ;</li>\n        <li><span class=\"kw-etio\">Dérivés nitrés</span> ;</li>\n        <li><span class=\"kw-etio\">Chirurgie bariatrique</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir :</strong> la <span class=\"kw-etio\">surcharge pondérale</span> explique la <strong><span class=\"kw-chiffre\">prévalence croissante</span></strong> du <span class=\"kw-clinique\">RGO</span> dans la population générale et conditionne directement sa prise en charge.</div>","frequence":2},{"id":"271-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la défaillance du sphincter inférieur de l’œsophage","contenu":"<p>La <strong>barrière anti-reflux œso-gastrique</strong> repose sur deux structures = <span class=\"kw-def\">SIO</span> (sphincter inférieur de l'œsophage) <strong>+ <span class=\"kw-def\">diaphragme</span></strong> ; sa <span class=\"kw-alerte\">défaillance</span> est l'<strong>élément clé</strong> de la <span class=\"kw-def\">physiopathologie</span> du <span class=\"kw-clinique\">RGO</span>.</p>\n      <p><strong>Rôle du SIO</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Zone de haute pression</span> qui <strong>s'oppose au gradient de pression abdomino-thoracique</strong> ;</li>\n        <li><span class=\"kw-clinique\">les</span> épisodes de <span class=\"kw-clinique\">RGO</span> surviennent surtout lors des <strong><span class=\"kw-clinique\">relaxations transitoires spontanées du SIO</span></strong> ;</li>\n        <li><span class=\"kw-clinique\">les</span> formes les plus <span class=\"kw-alerte\">sévères</span> de <span class=\"kw-clinique\">RGO</span> s'associent à une <span class=\"kw-alerte\">pression du SIO effondrée</span>.</li>\n      </ul>\n      <p><strong>Rôle du diaphragme</strong> : sa fonction de contention est diminuée, en particulier en cas de <span class=\"kw-etio\">hernie hiatale par roulement</span>.</p>\n      <p><strong>Autres mécanismes</strong> favorisants :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Stase gastrique</span> : <span class=\"kw-etio\">repas gras et calorique</span>, <span class=\"kw-etio\">gastroparésie</span> ;</li>\n        <li><span class=\"kw-clinique\">agression de la muqueuse œsophagienne</span> par le liquide gastrique (muqueuse non protégée) ;</li>\n        <li><span class=\"kw-clinique\">hyperpression abdominale</span> : <span class=\"kw-etio\">surcharge pondérale</span>, <span class=\"kw-etio\">effort de toux</span>, <span class=\"kw-etio\">effort à glotte fermée</span>, <span class=\"kw-etio\">vêtements serrés</span>.</li>\n      </ul>\n      <p><strong>Jonction œso-gastrique</strong> — repères de la <span class=\"kw-def\">ligne Z</span> :</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Position de la ligne Z</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Normale</strong></td><td>Ligne Z au niveau du <span class=\"kw-def\">hiatus diaphragmatique</span> et du <span class=\"kw-def\">passage intragastrique</span></td></tr>\n          <tr><td><strong>HH par glissement</strong></td><td>Ligne Z et passage intragastrique <strong>au-dessus</strong> du hiatus diaphragmatique</td></tr>\n          <tr><td><strong>EBO</strong></td><td>Ligne Z <strong>ascensionnée</strong> au-dessus du passage intragastrique et du hiatus</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-etio\">Hernie hiatale</span> = protrusion (permanente ou intermittente) d'une partie de l'estomac dans le thorax, à travers le hiatus œsophagien du diaphragme. Deux types (forme mixte possible) :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Glissement</th><th>Roulement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Proportion</strong></td><td><span class=\"kw-chiffre\">85 %</span></td><td><span class=\"kw-chiffre\">15 %</span></td></tr>\n          <tr><td><strong>Description</strong></td><td>Augmente le volume du refluxat lors des reflux ; n'emporte pas le péritoine</td><td>Grosse tubérosité formant une poche intrathoracique para-œsophagienne ; emporte le péritoine</td></tr>\n          <tr><td><strong>Position du cardia</strong></td><td>Intra-thoracique</td><td>Intra-abdominale</td></tr>\n          <tr><td><strong>Risque</strong></td><td>Ni nécessaire ni suffisante pour expliquer un <span class=\"kw-clinique\">RGO</span></td><td><span class=\"kw-alerte\">Étranglement herniaire</span> ; pas de lien avec le <span class=\"kw-clinique\">RGO</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Piège LISA :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">hernies hiatales ne se compliquent pas toutes de RGO</span> ; inversement, un <span class=\"kw-clinique\">RGO</span> peut exister <strong>sans hernie hiatale</strong>.</div>","frequence":0},{"id":"271-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les plaintes évoquant un RGO et les signes évoquant une pathologie néoplasique","contenu":"<p><strong>Symptômes typiques</strong> — leur association est <strong>quasi-pathognomonique</strong> du <span class=\"kw-clinique\">RGO</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Pyrosis</span> : <strong>brûlure rétrosternale ascendante</strong>, à point de départ <span class=\"kw-clinique\">épigastrique</span> ;</li>\n        <li><span class=\"kw-clinique\">Régurgitations acides</span> : remontées passives du contenu gastrique jusqu'au <span class=\"kw-clinique\">pharynx</span>, <strong>sans <span class=\"kw-clinique\">nausée</span> ni vomissement</strong>.</li>\n      </ul>\n      <p><strong>Caractères très évocateurs</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Post-prandial</span> ;</li>\n        <li><span class=\"kw-clinique\">Postural</span> : antéflexion du tronc (« <strong>signe du lacet</strong> ») et <span class=\"kw-clinique\">décubitus</span> ;</li>\n        <li><span class=\"kw-clinique\">Nocturne</span> → <span class=\"kw-alerte\">RGO souvent sévère, avec lésions d'œsophagite</span> ;</li>\n        <li>des <span class=\"kw-clinique\">brûlures épigastriques</span> isolées peuvent être le <strong>seul symptôme</strong> du <span class=\"kw-clinique\">RGO</span> — ne pas exiger un <span class=\"kw-clinique\">pyrosis</span> typique.</li>\n      </ul>\n      <p><strong>Symptômes extra-digestifs</strong> — associés aux signes digestifs ou <strong>isolés</strong> (évoquer un <span class=\"kw-clinique\">RGO</span> devant un bilan <span class=\"kw-imagerie\">ORL</span>, <span class=\"kw-imagerie\">pulmonaire</span> ou <span class=\"kw-imagerie\">cardiaque</span> normal) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Otalgie</span> (notamment à droite, par <span class=\"kw-clinique\">otalgie réflexe du IX</span>), <span class=\"kw-clinique\">sinusite</span> ;</li>\n        <li><span class=\"kw-clinique\">Érosions dentaires</span>, <span class=\"kw-clinique\">dysesthésies bucco-pharyngées</span> ;</li>\n        <li><span class=\"kw-clinique\">Enrouement</span>, <span class=\"kw-clinique\">pharyngite</span>, <span class=\"kw-clinique\">laryngite postérieure</span> ;</li>\n        <li><span class=\"kw-clinique\">Toux</span> (surtout en décubitus), <span class=\"kw-clinique\">dyspnée asthmatiforme</span>, <span class=\"kw-clinique\">fibrose pulmonaire</span> ;</li>\n        <li><span class=\"kw-clinique\">Troubles du sommeil</span> : <span class=\"kw-clinique\">micro-éveils nocturnes</span> avec retentissement diurne ;</li>\n        <li><span class=\"kw-clinique\">Douleurs précordiales pseudo-angineuses</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong> : <span class=\"kw-etio\">syndrome de rumination (mérycisme)</span>.</p>\n      <div class=\"callout callout-danger\"><strong>🚩 <span class=\"kw-alerte\">Drapeau rouge</span> — signes évoquant une pathologie <span class=\"kw-etio\">néoplasique</span> :</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Dysphagie</span> ;</li>\n          <li><span class=\"kw-clinique\">Amaigrissement</span> ;</li>\n          <li><span class=\"kw-alerte\">Anémie</span>.</li>\n        </ul>\n        Ces <strong><span class=\"kw-alerte\">signes d'alarme</span></strong> imposent une exploration endoscopique.</div>\n      <div class=\"callout callout-info\"><strong>Non-indication d'un bilan paraclinique</strong> — aucun examen complémentaire n'est nécessaire avant traitement si <span class=\"kw-clinique\">les</span> <strong>3 critères</strong> sont réunis :\n        <ul>\n          <li><span class=\"kw-chiffre\">Âge &lt; 50 ans</span> ;</li>\n          <li><span class=\"kw-clinique\">symptômes digestifs typiques</span> (<span class=\"kw-clinique\">pyrosis</span> et/ou régurgitations) ;</li>\n          <li><strong>aucun signe d'alarme</strong>.</li>\n        </ul></div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 273 — <span class=\"kw-clinique\">Dysphagie</span> · 305 — Tumeur de l'œsophage</em></p>","frequence":4},{"id":"271-4","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications : œsophagite, hémorragie, sténose, œsophage de Barrett (endobrachyœsophage)","contenu":"<p>Le <span class=\"kw-clinique\">RGO</span> chronique expose à <strong>deux grandes complications</strong> : l'<strong>œsophagite</strong> (et ses suites hémorragiques ou sténosantes) et l'<strong>endobrachyœsophage</strong>.</p>\n      <p><strong>1 · Œsophagite peptique</strong></p>\n      <ul>\n        <li>Concerne <span class=\"kw-chiffre\">40 %</span> des <span class=\"kw-clinique\">RGO</span> symptomatiques ; <strong>formes sévères</strong> <span class=\"kw-chiffre\">&lt; 5 %</span> ;</li>\n        <li>diagnostic <span class=\"kw-imagerie\">endoscopique</span> : <span class=\"kw-radio\">érythème</span>, <span class=\"kw-radio\">érosions</span>, <span class=\"kw-radio\">ulcérations</span> ;</li>\n        <li>sévérité cotée par la <span class=\"kw-def\">classification de Los Angeles</span> (grades A à D).</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span> Los Angeles</th><th>Lésions muqueuses</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td>≤ <span class=\"kw-chiffre\">5 mm</span>, sans <span class=\"kw-clinique\">lésion</span> entre le sommet de deux plis</td></tr>\n          <tr><td><strong>B</strong></td><td>&gt; <span class=\"kw-chiffre\">5 mm</span>, sans <span class=\"kw-clinique\">lésion</span> entre le sommet de deux plis</td></tr>\n          <tr><td><strong>C</strong></td><td>S'étendent entre le sommet de deux plis, &lt; <span class=\"kw-chiffre\">75 %</span> de la circonférence</td></tr>\n          <tr><td><strong>D</strong></td><td>&gt; <span class=\"kw-chiffre\">75 %</span> de la circonférence de l'œsophage</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>⚠ Pas de parallélisme</strong> entre l'intensité des <span class=\"kw-clinique\">symptômes</span> et la sévérité des <span class=\"kw-imagerie\">lésions endoscopiques</span> : un <span class=\"kw-clinique\">RGO</span> bruyant peut être sans œsophagite, une œsophagite sévère peut rester asymptomatique (sujet âgé).</div>\n      <p><strong>Suites de l'œsophagite</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Œsophagite ulcérée → hémorragie digestive</span> : <span class=\"kw-bio\">anémie ferriprive</span>, <span class=\"kw-alerte\">hématémèse</span>, <span class=\"kw-alerte\">méléna</span> ;</li>\n        <li><span class=\"kw-alerte\">RGO ancien → sténose peptique</span> : <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">amaigrissement</span>.</li>\n      </ul>\n      <p><strong>2 · Endobrachyœsophage (EBO / œsophage de Barrett)</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Métaplasie</span> glandulaire cylindrique remplaçant l'épithélium malpighien du <strong>1/3 distal de l'œsophage</strong>, sur <span class=\"kw-clinique\">RGO</span> chronique ;</li>\n        <li>survient chez <span class=\"kw-chiffre\">10-20 %</span> des sujets avec <span class=\"kw-clinique\">RGO</span> ;</li>\n        <li><span class=\"kw-clinique\">Pauci ou asymptomatique</span> — pas de symptôme spécifique, d'où la <strong><span class=\"kw-def\">surveillance</span> endoscopique systématique</strong> ;</li>\n        <li>diagnostic <span class=\"kw-imagerie\">endoscopique</span>, <strong>confirmé par l'anapath des biopsies</strong> (<span class=\"kw-bio\">métaplasie intestinale</span>).</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>🚩 Risque d'adénocarcinome :</strong> l'EBO multiplie le risque d'<span class=\"kw-alerte\">adénocarcinome de l'œsophage</span> par <span class=\"kw-chiffre\">30 à 100</span> — c'est le <strong>principal <span class=\"kw-def\">facteur de risque</span></strong> de cet ADK. Séquence : <span class=\"kw-def\">métaplasie sans dysplasie</span> → <span class=\"kw-alerte\">dysplasie de bas puis de haut grade</span> → adénocarcinome (risque <span class=\"kw-chiffre\">&lt; 1 %/an</span>).</div>\n      <p><strong><span class=\"kw-def\">Surveillance</span> de l'EBO</strong> — endoscopies avec <span class=\"kw-imagerie\">biopsies étagées multiples</span> ; le rythme dépend du statut dysplasique :</p>\n      <table >\n        <thead><tr><th>Statut dysplasique</th><th>Rythme de surveillance</th></tr></thead>\n        <tbody>\n          <tr><td>Pas de dysplasie</td><td>Endoscopie tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-5 ans</span> (rapprochée si EBO long)</td></tr>\n          <tr><td>Dysplasie de bas <span class=\"kw-def\">grade</span> <strong>suspectée</strong></td><td>Contrôle à <span class=\"kw-chiffre\">2-3 mois</span> après <span class=\"kw-ttt\">IPP double dose</span></td></tr>\n          <tr><td>Dysplasie de bas <span class=\"kw-def\">grade</span> <strong>confirmée</strong></td><td>Tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> la 1ʳᵉ année, puis <span class=\"kw-chiffre\">1×/an</span></td></tr>\n          <tr><td>Dysplasie de <strong>haut <span class=\"kw-def\">grade</span></strong></td><td>Contrôle à <span class=\"kw-chiffre\">M1</span> ; si confirmée → <span class=\"kw-ttt\">mucosectomie</span> ou <span class=\"kw-ttt\">chirurgie</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 305 — Tumeur de l'œsophage · 213 — Anémie</em></p>","frequence":2},{"id":"271-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication de l’endoscopie œsogastroduodénale si symptôme atypique ou début après 50 ans","contenu":"<p>L'<span class=\"kw-imagerie\">endoscopie œsogastroduodénale (FOGD)</span> est l'<span class=\"kw-imagerie\">examen morphologique de 1ʳᵉ intention</span> dans le <span class=\"kw-clinique\">RGO</span>.</p>\n      <p><strong>Indications de la <span class=\"kw-imagerie\">FOGD</span></strong> :</p>\n      <ul>\n        <li>Toujours indiquée si <span class=\"kw-chiffre\">âge &gt; 50 ans</span> ;</li>\n        <li>toujours indiquée en présence de <span class=\"kw-alerte\">signes d'alarme</span> : <span class=\"kw-clinique\">dysphagie</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-alerte\">hémorragie digestive</span>, <span class=\"kw-alerte\">anémie</span> ;</li>\n        <li>discutée en cas de <span class=\"kw-clinique\">signes atypiques</span> de <span class=\"kw-clinique\">RGO</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>⚠ Piège majeur :</strong> la <span class=\"kw-imagerie\">FOGD est normale dans <span class=\"kw-chiffre\">30-50 %</span> des cas</span> de <span class=\"kw-clinique\">RGO</span> — <strong>une <span class=\"kw-imagerie\">FOGD</span> normale ne permet donc pas d'écarter le diagnostic</strong>.</div>\n      <p><strong><span class=\"kw-imagerie\">Examens fonctionnels</span></strong> — <strong><span class=\"kw-alerte\">jamais en 1ʳᵉ intention</span></strong>, réalisés après une <span class=\"kw-imagerie\">FOGD</span> :</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">pH</span>-métrie des <span class=\"kw-chiffre\">24 h</span></strong></td><td><span class=\"kw-imagerie\">FOGD normale</span>, dans 3 situations : <span class=\"kw-clinique\">manifestations extra-digestives</span> ; <span class=\"kw-clinique\">persistance sous anti-sécrétoire</span> ; avant <span class=\"kw-ttt\">chirurgie anti-reflux</span></td><td><span class=\"kw-bio\">Exploration fonctionnelle la plus sensible</span> du <span class=\"kw-bio\">RGO acide pathologique</span></td></tr>\n          <tr><td><strong>Impédancemétrie</strong></td><td>Reflux persistant sous <span class=\"kw-ttt\">anti-sécrétoire</span></td><td>Met en évidence le <span class=\"kw-bio\">RGO peu ou non acide</span></td></tr>\n          <tr><td><strong>Manométrie</strong></td><td><span class=\"kw-clinique\">Trouble moteur œsophagien</span> ; <span class=\"kw-def\">bilan pré-opératoire</span></td><td><strong>N'objective pas le <span class=\"kw-clinique\">RGO</span></strong> ; identifie 2 facteurs aggravants : <span class=\"kw-clinique\">hypotonie franche du SIO</span>, <span class=\"kw-clinique\">troubles du péristaltisme</span> altérant la <span class=\"kw-bio\">clairance</span> acide</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-imagerie\">Transit baryté œso-gastrique</span> :</strong> <span class=\"kw-imagerie\">pas d'intérêt diagnostique</span> dans le <span class=\"kw-clinique\">RGO</span> ; utile exceptionnellement devant une <span class=\"kw-alerte\">sténose peptique</span> ou une <span class=\"kw-etio\">volumineuse hernie hiatale</span> (recherche de <span class=\"kw-imagerie\">réductibilité</span>).</div>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/esophagus-2","label":"Radiopaedia : Esophagus 2"},{"href":"https://radiopaedia.org/articles/hiatus-hernia","label":"Radiopaedia : Hiatus hernia"},{"href":"https://radiopaedia.org/articles/oesophagitis","label":"Radiopaedia : Oesophagitis"}]},{"id":"271-6","rang":"A","rubrique":"Prise en charge","titre":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">interventions non médicamenteuses</span> associent <strong><span class=\"kw-def\">règles hygiéno-diététiques (RHD)</span></strong> et <strong><span class=\"kw-ttt\">médicaments à effet topique</span></strong>.</p>\n      <p><strong><span class=\"kw-def\">Règles hygiéno-diététiques</span></strong> — recommandées malgré un <span class=\"kw-chiffre\">niveau de preuve faible</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Surélévation de la tête du lit</span> (~<span class=\"kw-chiffre\">45°</span>) ;</li>\n        <li>respect d'un intervalle <span class=\"kw-chiffre\">≥ 3 h</span> entre le dîner et le coucher ;</li>\n        <li><strong>correction de la <span class=\"kw-etio\">surcharge pondérale</span></strong> ;</li>\n        <li>éviction / limitation : <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">chocolat</span>, <span class=\"kw-etio\">café</span>, <span class=\"kw-etio\">tachyphagie</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir :</strong> la <strong><span class=\"kw-etio\">perte de poids</span></strong> (correction de la surcharge pondérale) est la mesure non médicamenteuse ayant <strong>le mieux prouvé son efficacité</strong>.</div>\n      <p><strong><span class=\"kw-ttt\">Médicaments à effet topique</span></strong> — agissent <span class=\"kw-bio\">localement</span>, sans inhiber la <span class=\"kw-bio\">sécrétion acide</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Alginate</span> : se dépose à la partie haute de l'<span class=\"kw-imagerie\">estomac</span> pour protéger la <span class=\"kw-imagerie\">muqueuse</span> lors du reflux ;</li>\n        <li><span class=\"kw-ttt\">Antiacides</span> : <span class=\"kw-ttt\">bicarbonate</span>, <span class=\"kw-ttt\">hydroxyde d'alumine ou de magnésium</span> — neutralisent l'<span class=\"kw-bio\">acidité luminale</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>⚠</strong> <span class=\"kw-clinique\">Les</span> topiques sont utiles si <span class=\"kw-clinique\">symptômes peu fréquents</span> (<span class=\"kw-ttt\">traitement à la demande</span>), mais <span class=\"kw-alerte\">ne permettent pas la cicatrisation</span> des <span class=\"kw-imagerie\">lésions d'œsophagite</span>.</div>","frequence":2},{"id":"271-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge médicamenteuse en cas de manque d’efficacité des interventions non médicamenteuses","contenu":"<p>La prise en charge médicamenteuse est indiquée <strong>en cas de manque d'efficacité des interventions non médicamenteuses</strong>. Elle dépend de la <strong>fréquence des symptômes</strong> et de la <strong>présence ou non d'une œsophagite</strong>.</p>\n      <p><strong>1 · <span class=\"kw-clinique\">RGO</span> non compliqué (sans œsophagite)</strong></p>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Symptômes intermittents ou peu invalidants (<span class=\"kw-chiffre\">&lt; 1/semaine</span>)</td><td><span class=\"kw-ttt\">Topiques</span> ou <span class=\"kw-ttt\">anti-H2</span>, puis <span class=\"kw-ttt\">IPP à la demande</span></td></tr>\n          <tr><td>Symptômes rapprochés (<span class=\"kw-chiffre\">&gt; 1/semaine</span>)</td><td><span class=\"kw-ttt\">IPP demi-dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span></td></tr>\n          <tr><td>Rechutes fréquentes / symptômes invalidants</td><td>Traitement continu par <span class=\"kw-ttt\">IPP</span> à la <strong>dose minimale efficace</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 · <span class=\"kw-clinique\">RGO</span> compliqué (œsophagite peptique)</strong> — objectif : maintenir un <span class=\"kw-bio\">pH gastrique &gt; 4</span> pour cicatriser <span class=\"kw-clinique\">les</span> lésions ; supériorité démontrée des <span class=\"kw-ttt\">IPP</span> sur les <span class=\"kw-ttt\">anti-H2</span> quelle que soit la sévérité.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Œsophagite <span class=\"kw-def\">grade</span> A/B</td><td><span class=\"kw-ttt\">IPP pleine dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span></td></tr>\n          <tr><td>Œsophagite <span class=\"kw-def\">grade</span> C/D</td><td><span class=\"kw-ttt\">IPP pleine dose</span> pendant <span class=\"kw-chiffre\">8 semaines</span> + <span class=\"kw-imagerie\">contrôle endoscopique</span></td></tr>\n          <tr><td>Sténose peptique</td><td><span class=\"kw-ttt\">IPP double dose</span> initialement, puis pleine dose au long cours ± <span class=\"kw-imagerie\">dilatation endoscopique</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>3 · <span class=\"kw-ttt\">Inhibiteurs de la pompe à protons</span> (<span class=\"kw-ttt\">IPP</span>)</strong></p>\n      <ul>\n        <li><strong>Mécanisme :</strong> inhibition des pompes à protons → <span class=\"kw-bio\">↑ pH gastrique</span> et <span class=\"kw-bio\">↑ non pathologique de la gastrinémie</span> ;</li>\n        <li><strong>traitement anti-sécrétoire de référence</strong> : <strong>supériorité démontrée sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">anti-H2</span></strong> (<span class=\"kw-ttt\">cimétidine</span>, <span class=\"kw-ttt\">famotidine</span>, <span class=\"kw-ttt\">ranitidine</span>), quelle que soit la sévérité de l'œsophagite ;</li>\n        <li><span class=\"kw-alerte\">aucune efficacité sur les régurgitations</span> ;</li>\n        <li><strong>prise :</strong> à jeun, le matin, <span class=\"kw-chiffre\">15-30 min avant le repas</span>.</li>\n      </ul>\n      <p><strong>Posologies des <span class=\"kw-ttt\">IPP</span> « -prazole » (mg)</strong> :</p>\n      <table >\n        <thead><tr><th>Molécule</th><th>Demi-dose</th><th>Pleine dose</th><th>Double dose</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Oméprazole</span></td><td><span class=\"kw-chiffre\">10</span></td><td><span class=\"kw-chiffre\">20</span></td><td><span class=\"kw-chiffre\">40</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Rabéprazole</span></td><td><span class=\"kw-chiffre\">10</span></td><td><span class=\"kw-chiffre\">20</span></td><td><span class=\"kw-chiffre\">40</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Lansoprazole</span></td><td><span class=\"kw-chiffre\">15</span></td><td><span class=\"kw-chiffre\">30</span></td><td><span class=\"kw-chiffre\">60</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Pantoprazole</span></td><td><span class=\"kw-chiffre\">20</span></td><td><span class=\"kw-chiffre\">40</span></td><td><span class=\"kw-chiffre\">80</span></td></tr>\n          <tr><td><span class=\"kw-ttt\">Ésoméprazole</span></td><td><span class=\"kw-chiffre\">20</span></td><td><span class=\"kw-chiffre\">40</span></td><td><span class=\"kw-chiffre\">80</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-ttt\">IPP</span> chez l'enfant :</strong>\n        <ul>\n          <li><span class=\"kw-chiffre\">&lt; 1 an</span> : <strong>pas d'AMM</strong>, sauf en cas d'<span class=\"kw-imagerie\">œsophagite</span> ;</li>\n          <li><span class=\"kw-chiffre\">1-12 ans</span> : <span class=\"kw-ttt\">oméprazole</span>, <span class=\"kw-ttt\">ésoméprazole</span> ;</li>\n          <li><span class=\"kw-chiffre\">&gt; 12 ans</span> : <span class=\"kw-ttt\">pantoprazole</span>.</li>\n        </ul></div>\n      <div class=\"callout callout-warn\"><strong>⚠ Effets secondaires des <span class=\"kw-ttt\">IPP</span></strong> (peu fréquents) :\n        <ul>\n          <li>à court terme : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">vertiges</span> ;</li>\n          <li>sur-risque d'<span class=\"kw-alerte\">infection bactérienne digestive</span> : <span class=\"kw-etio\">salmonelles non typhiques</span>, <span class=\"kw-etio\">C. difficile</span>, <span class=\"kw-etio\">campylobacter</span> ;</li>\n          <li>au long cours : <span class=\"kw-alerte\">ostéoporose</span>, <span class=\"kw-alerte\">fractures</span>, <span class=\"kw-alerte\">colite microscopique</span> ;</li>\n          <li>chez le <span class=\"kw-etio\">cirrhotique</span> : sur-risque d'<span class=\"kw-alerte\">infection du liquide d'ascite</span> — la consommation abusive est associée à une <span class=\"kw-alerte\">surmortalité</span> ;</li>\n          <li><strong>nombreuses <span class=\"kw-alerte\">interactions médicamenteuses</span></strong> (notamment <span class=\"kw-ttt\">clopidogrel</span>).</li>\n        </ul>\n        <strong>Pas d'association avec la survenue de cancers</strong> ; <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">IPP</span> <strong>ne préviennent pas la dysplasie</strong> ni le cancer sur EBO.</div>\n      <p><strong>4 · <span class=\"kw-ttt\">Chirurgie</span></strong> — devenue l'<strong>exception</strong> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Fundoplicature par cœlioscopie</span> : <strong>Nissen</strong> (fundoplicature complète, la plus utilisée) ou <strong>Toupet</strong> (hémifundoplicature postérieure) ;</li>\n        <li><span class=\"kw-def\">bilan pré-opératoire</span> par <span class=\"kw-imagerie\">manométrie</span> ± <span class=\"kw-imagerie\">pH-métrie</span> ;</li>\n        <li><strong>indications :</strong> récidive dès l'arrêt du traitement ; <span class=\"kw-clinique\">régurgitations</span> gênantes persistantes ; volumineuse hernie hiatale ; reflux anormal documenté sous traitement.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À noter :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-ci\">traitements prokinétiques</span> n'ont <strong>pas d'intérêt</strong> dans le <span class=\"kw-clinique\">RGO</span>.</div>\n      <div class=\"callout callout-info\"><strong>Test thérapeutique :</strong> devant une <span class=\"kw-clinique\">toux chronique</span> sans orientation, un traitement d'épreuve par <span class=\"kw-ttt\">IPP double dose</span> pendant <span class=\"kw-chiffre\">8 semaines</span> peut être proposé, après exclusion d'une cause <span class=\"kw-imagerie\">ORL</span> ou <span class=\"kw-imagerie\">pulmonaire</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span> · 204 — <span class=\"kw-clinique\">Toux</span> · 330 — Prescription et <span class=\"kw-def\">surveillance</span> des médicaments - hors anti-<span class=\"kw-etio\">infectieux</span></em></p>","frequence":6}],"astuces":[{"type":"tip","titre":"Mnémo « PRADHA » — signes d'alarme imposant l'EOGD","contenu":"<p><strong>P</strong>erte de poids · <strong>R</strong>égurgitations + <span class=\"kw-clinique\">dysphagie</span> · <strong>A</strong>némie ferriprive · <strong>D</strong>ysphagie / <span class=\"kw-clinique\">odynophagie</span> · <strong>H</strong>émorragie digestive · <strong>A</strong>pparition ≥ <span class=\"kw-chiffre\">50 ans</span> (ou ATCD familial de K œsogastrique). Devant n'importe lequel de ces signes : <strong><span class=\"kw-imagerie\">EOGD</span> avec <span class=\"kw-imagerie\">biopsies</span> <span class=\"kw-alerte\">sans délai</span></strong>, <span class=\"kw-ci\">jamais de traitement à l'aveugle</span>.</p>"},{"type":"warn","titre":"Hernie hiatale : glissement ≠ roulement","contenu":"<table class=\"matrix\"><thead><tr><th></th><th>Par glissement (<span class=\"kw-chiffre\">90 %</span>)</th><th>Par roulement (<span class=\"kw-chiffre\">10 %</span>)</th></tr></thead><tbody><tr><td>Anatomie</td><td>Cardia remonte dans le thorax</td><td>Cardia en place, grosse tubérosité à côté de l'œsophage</td></tr><tr><td>Clinique</td><td><ul><li>Souvent asymptomatique</li><li>Favorise le <span class=\"kw-def\">RGO</span></li></ul></td><td><ul><li>Pas de <span class=\"kw-def\">RGO</span></li><li><span class=\"kw-clinique\">Pesanteur</span>, <span class=\"kw-clinique\">dyspnée</span></li><li><span class=\"kw-alerte\">Risque</span> de <span class=\"kw-alerte\">volvulus / étranglement</span></li></ul></td></tr><tr><td><span class=\"kw-def\">PEC</span></td><td><ul><li><span class=\"kw-ttt\">Traitement</span> du <span class=\"kw-def\">RGO</span> si symptomatique</li><li>Pas de <span class=\"kw-ttt\">chirurgie</span> sur la hernie isolée</li></ul></td><td><ul><li><span class=\"kw-ttt\">Chirurgie</span> systématique si symptomatique</li><li><span class=\"kw-alerte\">Urgence</span> si <span class=\"kw-alerte\">étranglée</span></li></ul></td></tr></tbody></table>"},{"type":"tip","titre":"Endobrachyœsophage — protocole de Seattle","contenu":"<p>Devant une <strong><span class=\"kw-clinique\">métaplasie intestinale</span></strong> du bas œsophage (<span class=\"kw-def\">Barrett</span>) : <span class=\"kw-imagerie\">biopsies étagées</span> <strong>tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 cm</span></strong> sur les 4 quadrants + <span class=\"kw-imagerie\">biopsies ciblées</span> sur toute <span class=\"kw-clinique\">lésion</span> suspecte. <span class=\"kw-def\">Classification</span> de <strong><span class=\"kw-def\">Prague</span> C&amp;M</strong> : <span class=\"kw-radio\">C = longueur circonférentielle</span>, <span class=\"kw-radio\">M = longueur maximale</span> (ex : <span class=\"kw-radio\">C2M5</span> = <span class=\"kw-chiffre\">2 cm</span> circonférentiel et <span class=\"kw-chiffre\">5 cm</span> en langue). <span class=\"kw-def\">Surveillance</span> : /<span class=\"kw-chiffre\">3-5 ans</span> si &lt; <span class=\"kw-chiffre\">3 cm</span> sans <span class=\"kw-clinique\">dysplasie</span>, /<span class=\"kw-chiffre\">2-3 ans</span> si ≥ <span class=\"kw-chiffre\">3 cm</span>, /<span class=\"kw-chiffre\">6-12 mois</span> si <span class=\"kw-clinique\">dysplasie</span> de <span class=\"kw-alerte\">bas grade</span>, <strong><span class=\"kw-ttt\">résection endoscopique muqueuse</span> + <span class=\"kw-ttt\">radiofréquence</span></strong> si <span class=\"kw-alerte\">haut grade</span> ou <span class=\"kw-alerte\">K intra-muqueux</span>.</p>"},{"type":"info","titre":"IPP — pièges de prescription","contenu":"<ul><li><strong>Prise <span class=\"kw-chiffre\">30 min</span> avant le petit-déjeuner</strong> (l'<span class=\"kw-ttt\">IPP</span> bloque <span class=\"kw-clinique\">les</span> pompes activées par le repas) — <span class=\"kw-ci\">pas au coucher</span>, <span class=\"kw-ci\">pas pendant le repas</span>.</li><li><strong><span class=\"kw-ttt\">Demi-dose</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-ttt\">pleine dose</span></strong> : retenir <span class=\"kw-ttt\">oméprazole</span> 10 / <span class=\"kw-chiffre\">20 mg</span>, <span class=\"kw-ttt\">ésoméprazole</span> 20 / <span class=\"kw-chiffre\">40 mg</span>, <span class=\"kw-ttt\">pantoprazole</span> 20 / <span class=\"kw-chiffre\">40 mg</span>.</li><li><strong>Œsophagite <span class=\"kw-radio\">LA C-D</span> = <span class=\"kw-ttt\">pleine dose</span> <span class=\"kw-chiffre\">8 sem</span> + <span class=\"kw-imagerie\">EOGD</span> de contrôle</strong> (recherche d'<span class=\"kw-def\">EBO</span> masqué par l'inflammation).</li><li><strong>Au long cours</strong> : <span class=\"kw-ttt\">dose minimale efficace</span>, <strong><span class=\"kw-def\">réévaluation</span> annuelle</strong>, vigilance ↓ <span class=\"kw-bio\">B12</span> / <span class=\"kw-bio\">Mg</span>, néphrite, <em><span class=\"kw-etio\">C. difficile</span></em>, <span class=\"kw-clinique\">pneumopathie</span>.</li><li><strong><span class=\"kw-ci\">Pas de prokinétique</span> de principe</strong> (<span class=\"kw-ttt\">métoclopramide</span> = AP caché D2, <span class=\"kw-ttt\">dompéridone</span> = <span class=\"kw-alerte\">QT long</span>).</li></ul>"}],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">Dysphagie</span> → évoquer une <span class=\"kw-etio\">sténose peptique</span> ou une <span class=\"kw-etio\">pathologie néoplasique</span></li><li><span class=\"kw-alerte\">Amaigrissement</span> → signe d'alarme évoquant une <span class=\"kw-etio\">néoplasie œsophagienne</span></li><li><span class=\"kw-alerte\">Anémie</span> ferriprive → <span class=\"kw-etio\">hémorragie digestive</span> occulte sur œsophagite ulcérée</li><li><span class=\"kw-alerte\">Hémorragie digestive</span> patente : <span class=\"kw-clinique\">hématémèse</span>, <span class=\"kw-clinique\">méléna</span></li><li>Apparition des symptômes <span class=\"kw-alerte\">après 50 ans</span> → <span class=\"kw-imagerie\">FOGD</span> systématique avant traitement</li><li>Symptômes <span class=\"kw-clinique\">nocturnes</span> → <span class=\"kw-clinique\">RGO</span> souvent <span class=\"kw-alerte\">sévère</span>, avec <span class=\"kw-clinique\">lésions d'œsophagite</span></li><li><span class=\"kw-def\">Endobrachyœsophage (EBO)</span> → multiplie <span class=\"kw-chiffre\">×30-100</span> le risque d'<span class=\"kw-etio\">adénocarcinome de l'œsophage</span> (principal <span class=\"kw-def\">facteur de risque</span>)</li></ul>","principes":"<p><strong>Triple objectif :</strong> soulager le patient, cicatriser <span class=\"kw-clinique\">les</span> lésions d'<span class=\"kw-clinique\">œsophagite</span>, prévenir les <span class=\"kw-alerte\">complications</span> et les récidives sévères. Les <span class=\"kw-ttt\">IPP</span> sont le traitement médical de référence, à la <strong>dose minimale efficace</strong> ; les <span class=\"kw-ci\">traitements prokinétiques</span> n'ont aucun intérêt dans le <span class=\"kw-clinique\">RGO</span>.</p><p><strong>Interventions non médicamenteuses <span class=\"q\">— <span class=\"kw-ttt\">RHD</span> (rang A)</span></strong></p><p>niveau de preuve faible, mais à recommander en <span class=\"kw-chiffre\">première intention</span></p><ul><li>Surélévation de la tête du lit (<span class=\"kw-chiffre\">~45°</span>)</li><li>Respect d'un intervalle <span class=\"kw-chiffre\">≥ 3 h</span> entre le dîner et le coucher</li><li>Perte de poids ; éviter <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, <span class=\"kw-etio\">chocolat</span>, <span class=\"kw-etio\">café</span>, <span class=\"kw-etio\">tachyphagie</span></li></ul><p><strong>Médicaments à effet topique</strong></p><p>ne permettent <strong>pas</strong> la cicatrisation des lésions d'<span class=\"kw-clinique\">œsophagite</span></p><ul><li>Anti-acides (<span class=\"kw-ttt\">bicarbonate</span>, <span class=\"kw-ttt\">hydroxyde d'alumine/de magnésium</span>) : neutralisent l'acidité luminale</li><li><span class=\"kw-ttt\">Alginate de sodium</span> : se dépose en surface et protège la muqueuse</li><li>utiles si symptômes <span class=\"kw-clinique\">peu fréquents</span> → traitements <strong>à la demande</strong></li></ul><p><strong>Anti-sécrétoires</strong></p><ul><li><span class=\"kw-ttt\">Anti-H2</span> (cimétidine, famotidine, <span class=\"kw-ttt\">ranitidine</span>) : efficaces sur <span class=\"kw-clinique\">les</span> symptômes, moins prescrits</li><li><span class=\"kw-ttt\">IPP</span> = traitement de référence (<span class=\"kw-clinique\">les</span> plus efficaces) ; prise quotidienne à jeun, <span class=\"kw-chiffre\">15-30 min</span> avant le repas</li><li>doses modulées de la <span class=\"kw-chiffre\">demi-dose</span> en cure courte à la <span class=\"kw-chiffre\">double dose</span> prolongée selon symptômes/complications</li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> <span class=\"q\">— devenue l'exception</span></strong></p><p>réservée aux <span class=\"kw-clinique\">RGO</span> résistants/récidivants avec reflux anormal documenté (voir arbre)</p><ul><li><span class=\"kw-ttt\">Fundoplicature par cœlioscopie</span> : <span class=\"kw-ttt\">Nissen</span> (complète, la plus utilisée) ou <span class=\"kw-ttt\">Toupet</span> (hémifundoplicature postérieure)</li><li><span class=\"kw-def\">bilan pré-opératoire</span> par <span class=\"kw-imagerie\">manométrie</span> ± <span class=\"kw-imagerie\">pH-métrie</span></li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">RGO</span> non compliqué :</strong> au long cours, <span class=\"kw-ttt\">IPP à la demande</span> à la <strong>dose minimale efficace</strong> ; <span class=\"kw-clinique\">les</span> récidives à l'arrêt sont d'autant plus fréquentes que l'<span class=\"kw-clinique\">œsophagite</span> était sévère. Les <span class=\"kw-ttt\">IPP</span> ne préviennent <strong>ni</strong> la <span class=\"kw-clinique\">dysplasie</span> <strong>ni</strong> le cancer sur EBO.</p><p><strong>Œsophagite sévère (<span class=\"kw-def\">grade</span> C/D)</strong></p><ul><li><span class=\"kw-imagerie\">Contrôle endoscopique</span> de la cicatrisation après <span class=\"kw-ttt\">IPP pleine dose</span> <span class=\"kw-chiffre\">8 semaines</span></li></ul><p><strong><span class=\"kw-def\">Surveillance</span> de l'EBO (endobrachyœsophage)</strong></p><p>la <span class=\"kw-def\">surveillance</span> dépend de la hauteur de l'atteinte et du <span class=\"kw-def\">grade</span> de dysplasie</p><ul><li><strong>Pas de dysplasie :</strong> <span class=\"kw-imagerie\">endoscopie + biopsies étagées</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2-5 ans</span> (rapprochée si EBO long)</li><li><strong>Dysplasie de bas <span class=\"kw-def\">grade</span> suspectée :</strong> contrôle à <span class=\"kw-chiffre\">2-3 mois</span> après <span class=\"kw-ttt\">IPP double dose</span></li><li><strong>Dysplasie de bas <span class=\"kw-def\">grade</span> confirmée :</strong> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span> la 1ʳᵉ année, puis <span class=\"kw-chiffre\">1×/an</span></li><li><strong>Dysplasie de haut <span class=\"kw-def\">grade</span> :</strong> contrôle à <span class=\"kw-chiffre\">M1</span>, puis si confirmée → <span class=\"kw-ttt\">mucosectomie</span> ou <span class=\"kw-ttt\">chirurgie</span></li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/reflux-gastro-oesophagien-nourrisson-lenfant","label":"Pedia-univ — Reflux gastro oesophagien nourrisson lenfant"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Symptômes évoquant un RGO — Pyrosis ± régurgitations acides (association quasi-pathognomonique)","detail":"<h4>CAT — <span class=\"kw-clinique\">reflux gastro-œsophagien</span> — Qui explorer (<span class=\"kw-imagerie\">FOGD</span>) ? Quelle stratégie thérapeutique ?</h4>","branches":[{"to":"q-frequence","label":"< 50 ans · symptômes typiques · AUCUN signe d'alarme","color":"green"},{"to":"q-fogd","label":"≥ 50 ans · signe d'alarme (dysphagie, amaigrissement, anémie, hémorragie) · ou symptômes atypiques","color":"amber"}]},{"id":"q-frequence","kind":"decision","label":"Aucun examen complémentaire — traitement selon la fréquence — RGO non compliqué présumé (pas de FOGD requise)","branches":[{"to":"t-demande","label":"Intermittents ou peu invalidants (< 1×/semaine)","color":"green"},{"to":"t-ipp-demi","label":"Rapprochés (> 1×/semaine)","color":"amber"},{"to":"q-resistance","label":"Rechutes fréquentes/précoces, invalidant ou résistance","color":"amber"}]},{"id":"t-demande","kind":"terminal","label":"Traitement à la demande","color":"green","detail":"<h4>Indication</h4><ul><li>Symptômes <span class=\"kw-clinique\">typiques</span> <span class=\"kw-chiffre\">&lt; 1×/semaine</span>, intermittents ou peu invalidants ; <span class=\"kw-alerte\">aucun examen complémentaire</span> (&lt;<span class=\"kw-chiffre\"> 50 ans</span>, sans signe d'alarme).</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Médicaments à effet topique</span> : <span class=\"kw-ttt\">alginate de sodium</span>, <span class=\"kw-ttt\">bicarbonate</span>, <span class=\"kw-ttt\">hydroxyde d'alumine/de magnésium</span></li><li><span class=\"kw-ttt\">Anti-H2</span> ou <span class=\"kw-ttt\">IPP à la demande</span> au long cours</li><li><span class=\"kw-ttt\">RHD</span> associées</li></ul><h4>Limite</h4><ul><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">topiques</span> ne cicatrisent <strong>pas</strong> les lésions d'<span class=\"kw-clinique\">œsophagite</span>.</li></ul>"},{"id":"t-ipp-demi","kind":"terminal","label":"IPP demi-dose — 4 semaines","color":"amber","detail":"<h4>Indication</h4><ul><li>Symptômes typiques <strong>rapprochés</strong> (<span class=\"kw-chiffre\">&gt; 1×/semaine</span>), <span class=\"kw-clinique\">RGO</span> non compliqué.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP à demi-dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span> (<strong>sauf <span class=\"kw-ttt\">oméprazole</span></strong> : pleine dose).</li></ul><h4>Si échec / rechute</h4><ul><li>Rechutes fréquentes/précoces ou symptômes invalidants → passer au <span class=\"kw-ttt\">traitement continu</span> à dose minimale efficace.</li></ul>"},{"id":"q-resistance","kind":"decision","label":"RGO résistant à un traitement médical bien conduit ? — Documenter par pH-métrie + pH-impédancemétrie un reflux persistant","branches":[{"to":"t-continu","label":"RGO contrôlé / pas de reflux documenté","color":"green"},{"to":"t-chirurgie","label":"Reflux acide persistant documenté ± volumineuse hernie hiatale","color":"blue"}]},{"id":"t-continu","kind":"terminal","label":"IPP continu — dose minimale efficace","color":"green","detail":"<h4>Indication</h4><ul><li>Rechutes fréquentes/précoces ou symptômes invalidants, <span class=\"kw-clinique\">RGO</span> contrôlé sous traitement, sans critère chirurgical.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP</span> en continu (demi ou pleine dose), à la <strong>dose minimale efficace</strong>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Récidives à l'arrêt d'autant plus fréquentes que l'<span class=\"kw-clinique\">œsophagite</span> était sévère.</li></ul>"},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie anti-reflux (après pH-métrie)","color":"blue","detail":"<h4>Indications</h4><ul><li><span class=\"kw-clinique\">RGO</span> <span class=\"kw-clinique\">résistant</span> à un traitement médical bien conduit, reflux persistant documenté</li><li><span class=\"kw-clinique\">Récidive</span> systématique à l'arrêt nécessitant un traitement continu</li><li><span class=\"kw-clinique\">Régurgitations</span> gênantes persistantes</li><li>Volumineuse <span class=\"kw-etio\">hernie hiatale</span></li></ul><h4><span class=\"kw-def\">Bilan pré-opératoire</span></h4><ul><li><span class=\"kw-imagerie\">pH-métrie</span> / <span class=\"kw-imagerie\">pH-impédancemétrie</span> + <span class=\"kw-imagerie\">manométrie</span> (écarter un trouble moteur de l'œsophage).</li></ul><h4>Technique</h4><ul><li><span class=\"kw-ttt\">Fundoplicature par cœlioscopie</span> : <span class=\"kw-ttt\">Nissen</span> (complète, la plus utilisée) ou <span class=\"kw-ttt\">Toupet</span> (hémifundoplicature postérieure).</li></ul>"},{"id":"q-fogd","kind":"decision","label":"FOGD (endoscopie œsogastroduodénale) — résultat ? — Indication formelle ; normale dans 30-50 % des cas (n'élimine pas le RGO)","branches":[{"to":"t-ipp-pleine","label":"Œsophagite peptique (grade A à D)","color":"amber"},{"to":"t-stenose","label":"Sténose peptique","color":"amber"}]},{"id":"t-ipp-pleine","kind":"terminal","label":"IPP pleine dose — 4 / 8 semaines","color":"amber","detail":"<h4>Œsophagite peu sévère (<span class=\"kw-def\">grade</span> A/B)</h4><ul><li><span class=\"kw-ttt\">IPP pleine dose</span> pendant <span class=\"kw-chiffre\">4 semaines</span>, puis prévention des récidives à dose minimale efficace.</li></ul><h4>Œsophagite sévère (<span class=\"kw-def\">grade</span> C/D)</h4><ul><li><span class=\"kw-ttt\">IPP pleine dose</span> pendant <span class=\"kw-chiffre\">8 semaines</span> avec <span class=\"kw-imagerie\">contrôle endoscopique</span> de la cicatrisation.</li></ul><h4>Objectif</h4><ul><li><span class=\"kw-bio\">pH</span> gastrique maintenu <span class=\"kw-chiffre\">&gt; 4</span> ; supériorité des <span class=\"kw-ttt\">IPP</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">anti-H2</span> démontrée quelle que soit la sévérité.</li></ul>"},{"id":"t-stenose","kind":"terminal","label":"Sténose peptique — IPP double dose","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Dysphagie</span> + <span class=\"kw-alerte\">amaigrissement</span> sur <span class=\"kw-clinique\">RGO</span> ancien.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP double dose</span> initialement, puis <span class=\"kw-ttt\">IPP pleine dose</span> au long cours</li><li><span class=\"kw-ttt\">Dilatation endoscopique</span> à discuter au cas par cas (pour améliorer la <span class=\"kw-clinique\">dysphagie</span>)</li></ul>"}]},"cards":[{"i":"1d5591f018fb","n":271,"o":"271-3","u":"Diagnostic positif","t":"Connaître les plaintes évoquant un RGO et les signes évoquant une pathologie néoplasique","q":"Quels sont les symptômes digestifs typiques évoquant un RGO ?","a":"<p>Les symptômes digestifs typiques, dont l'association est quasi-pathognomonique du RGO, sont :</p><ul><li>Le <strong>pyrosis</strong> : brûlure rétrosternale ascendante, à point de départ épigastrique.</li><li>Les <strong>régurgitations acides</strong> : remontées passives du contenu gastrique jusqu'au pharynx, sans nausée ni vomissement.</li></ul><p>Ces symptômes sont particulièrement évocateurs lorsqu'ils sont <strong>post-prandiaux</strong>, <strong>posturaux</strong> (signe du lacet), ou <strong>nocturnes</strong> (évoquant un RGO sévère).</p>"},{"i":"42aa41103213","n":271,"o":"271-3","u":"Diagnostic positif","t":"Connaître les plaintes évoquant un RGO et les signes évoquant une pathologie néoplasique","q":"Quels sont les signes d'alerte devant faire rechercher une pathologie néoplasique en présence de symptômes de RGO ?","a":"<p>Les signes d'alerte, appelés \"drapeaux rouges\", qui imposent une exploration endoscopique pour rechercher une pathologie néoplasique sont :</p><ul><li>La <strong>dysphagie</strong>.</li><li>L'<strong>amaigrissement</strong>.</li><li>L'<strong>anémie</strong>.</li></ul>"},{"i":"b663bd77adb9","n":271,"o":"271-3","u":"Diagnostic positif","t":"Connaître les plaintes évoquant un RGO et les signes évoquant une pathologie néoplasique","q":"Quels sont les symptômes extra-digestifs pouvant évoquer un RGO ?","a":"<p>Le RGO peut se manifester par des symptômes extra-digestifs, parfois isolés, nécessitant d'évoquer un RGO devant un bilan ORL, pulmonaire ou cardiaque normal :</p><ul><li><strong>ORL</strong> : otalgie (notamment à droite, par otalgie réflexe du IX), sinusite, érosions dentaires, dysesthésies bucco-pharyngées, enrouement, pharyngite, laryngite postérieure.</li><li><strong>Pulmonaire</strong> : toux (surtout en décubitus), dyspnée asthmatiforme, fibrose pulmonaire.</li><li><strong>Cardiaque</strong> : douleurs précordiales pseudo-angineuses.</li><li><strong>Généraux</strong> : troubles du sommeil (micro-éveils nocturnes avec retentissement diurne).</li></ul>"},{"i":"77ced1f84212","n":271,"o":"271-4","u":"Suivi et/ou pronostic","t":"Connaître les principales complications : œsophagite, hémorragie, sténose, œsophage de Barrett (endobrachyœsophage)","q":"Comment est diagnostiquée une œsophagite peptique et quelles sont les principales complications qu'elle peut entraîner ?","a":"<p>L'œsophagite peptique est diagnostiquée par <strong>endoscopie</strong>, révélant érythème, érosions ou ulcérations. Sa sévérité est classée par la classification de <strong>Los Angeles</strong> (grades A à D).</p><p>Les principales complications sont :</p><ul><li>L'<strong>hémorragie digestive</strong> (anémie ferriprive, hématémèse, méléna) due à une œsophagite ulcérée.</li><li>La <strong>sténose peptique</strong> (dysphagie, amaigrissement) due à un RGO chronique ancien.</li></ul>"},{"i":"a88214dd9330","n":271,"o":"271-4","u":"Suivi et/ou pronostic","t":"Connaître les principales complications : œsophagite, hémorragie, sténose, œsophage de Barrett (endobrachyœsophage)","q":"Quelles sont les deux grandes complications d'un reflux gastro-œsophagien (RGO) chronique ?","a":"<p>Les deux grandes complications d'un RGO chronique sont :</p><ul><li>L'<strong>œsophagite peptique</strong> et ses suites (hémorragiques ou sténosantes).</li><li>L'<strong>endobrachyœsophage</strong> (EBO ou œsophage de Barrett).</li></ul>"},{"i":"b878bcfa798b","n":271,"o":"271-4","u":"Suivi et/ou pronostic","t":"Connaître les principales complications : œsophagite, hémorragie, sténose, œsophage de Barrett (endobrachyœsophage)","q":"Quelle est la définition de l'endobrachyœsophage (EBO) et quel est son principal risque évolutif ?","a":"<p>L'endobrachyœsophage (EBO), ou œsophage de Barrett, est une <strong>métaplasie glandulaire cylindrique</strong> remplaçant l'épithélium malpighien du tiers distal de l'œsophage, survenant suite à un RGO chronique.</p><p>Son principal risque évolutif est l'apparition d'un <strong>adénocarcinome de l'œsophage</strong>, l'EBO multipliant ce risque par <strong>30 à 100</strong>. L'évolution se fait de la métaplasie sans dysplasie vers la dysplasie de bas puis de haut grade, avant l'adénocarcinome.</p>"},{"i":"e988168f7048","n":271,"o":"271-4","u":"Suivi et/ou pronostic","t":"Connaître les principales complications : œsophagite, hémorragie, sténose, œsophage de Barrett (endobrachyœsophage)","q":"Comment est surveillé un endobrachyœsophage (EBO) et quelle est l'importance du statut dysplasique ?","a":"<p>L'EBO est surveillé par <strong>endoscopies avec biopsies étagées multiples</strong>. Le rythme de surveillance dépend du <strong>statut dysplasique</strong> :</p><ul><li><strong>Pas de dysplasie</strong> : endoscopie tous les <strong>2 à 5 ans</strong>.</li><li><strong>Dysplasie de bas grade confirmée</strong> : tous les <strong>6 mois</strong> la première année, puis <strong>annuellement</strong>.</li><li><strong>Dysplasie de haut grade</strong> : contrôle à 1 mois, puis si confirmée, envisager <strong>mucosectomie ou chirurgie</strong>.</li></ul>"},{"i":"53f2782f4382","n":271,"o":"271-6","u":"Prise en charge","t":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","q":"Quelles sont les principales règles hygiéno-diététiques (RHD) recommandées pour le reflux gastro-œsophagien (RGO) ?","a":"<ul><li><strong>Surélévation de la tête du lit</strong> (environ 45°).</li><li>Respecter un intervalle d'au moins <strong>3 heures entre le dîner et le coucher</strong>.</li><li>Correction d'une éventuelle <strong>surcharge pondérale</strong>.</li><li>Éviction ou limitation du <strong>tabac</strong>, de l'<strong>alcool</strong>, du <strong>chocolat</strong>, du <strong>café</strong> et de la <strong>tachyphagie</strong>.</li></ul>"},{"i":"64e95f2f9120","n":271,"o":"271-6","u":"Prise en charge","t":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","q":"Quels sont les objectifs des interventions non médicamenteuses dans la prise en charge du reflux gastro-œsophagien (RGO) ?","a":"<p>Les interventions non médicamenteuses dans le RGO visent à réduire les symptômes et prévenir les complications, en associant des règles hygiéno-diététiques et l'utilisation de médicaments à effet topique.</p>"},{"i":"735ba4c2ae74","n":271,"o":"271-6","u":"Prise en charge","t":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","q":"Parmi les règles hygiéno-diététiques, quelle est la mesure non médicamenteuse ayant le mieux prouvé son efficacité dans le reflux gastro-œsophagien (RGO) ?","a":"<p>La <strong>perte de poids</strong> (correction de la surcharge pondérale) est la mesure non médicamenteuse ayant le mieux prouvé son efficacité dans la prise en charge du RGO.</p>"},{"i":"7d2e2a8a2659","n":271,"o":"271-6","u":"Prise en charge","t":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","q":"Comment agissent les médicaments à effet topique (alginates et antiacides) dans le reflux gastro-œsophagien (RGO) ?","a":"<ul><li>Les <strong>alginates</strong> se déposent à la partie haute de l'estomac pour protéger la muqueuse lors du reflux.</li><li>Les <strong>antiacides</strong> (bicarbonate, hydroxyde d'alumine ou de magnésium) neutralisent l'acidité luminale.</li></ul><p>Ces médicaments agissent localement et n'inhibent pas la sécrétion acide.</p>"},{"i":"fb81f57e7dde","n":271,"o":"271-6","u":"Prise en charge","t":"Connaître les différentes interventions non médicamenteuses possibles, en particulier celles ayant prouvé leur efficacité","q":"Quelle est l'indication des médicaments à effet topique (alginates et antiacides) dans la prise en charge du reflux gastro-œsophagien (RGO) ?","a":"<p>Les topiques sont utiles si les symptômes sont peu fréquents (<strong>traitement à la demande</strong>). Cependant, ils ne permettent pas la cicatrisation des lésions d'œsophagite.</p>"}]};